// Extrai os dados enviados pelo app
const data = $input.first().json.body || $input.first().json;

const creatorName = data.creator_name || 'Tenista da Montreal';
const level = data.level || 'C';
const gender = data.gender_category || 'Masculino';
const date = data.friendly_date || data.game_date || 'A definir';
const time = data.friendly_time || data.start_time || '18:00';
const duration = data.duration_minutes ? `${data.duration_minutes} min` : '60 min';
const gameId = data.game_id || '';
const gameLink = data.game_link || `https://montreal-ranking.app/#/jogos/${gameId}`;

// Determina quais níveis são elegíveis para disputar
let allowedText = 'Jogadores de Nível ' + level;
if (level === 'A') allowedText = 'Jogadores de Nível A e B';
else if (level === 'B') allowedText = 'Jogadores de Nível B e C';
else if (level === 'C') allowedText = 'Jogadores de Nível C e D';
else if (level === 'D') allowedText = 'Jogadores de Nível D';

const message = `🎾 *NOVO DESAFIO ABERTO NO RANKING!*\n\n👤 *Criador:* ${creatorName}\n🏆 *Nível da Partida:* Nível ${level} (${gender})\n👥 *Quem pode entrar:* ${allowedText}\n📅 *Data:* ${date} às ${time}\n⏱️ *Duração:* ${duration}\n🎾 *Formato:* 1 Set até 8 games (No-Ad)\n📍 *Local:* Montreal Tênis Clube\n\nQuem topa o desafio? Acesse o link abaixo e clique em *"Entrar na Partida"*:\n👉 ${gameLink}`;

return [{
  json: {
    number: "120363428928893345@g.us",
    text: message,
    game_id: gameId,
    creator: creatorName,
    level: level
  }
}];

